def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    barriers = [r for r, row in enumerate(grid) if all(v == 2 for v in row)]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != 4:
                continue
            wall = next((b for b in barriers if b > r), h)
            impact = wall - 1
            # Particles drop vertically, then form a diagonal ray extending
            # up-left from the impact point; reflected rays form the splash.
            for d in range(max(0, impact-r)+1):
                rr = impact-d
                cc = c-d
                if 0 <= cc < w:
                    out[rr][cc] = 4
            out[impact][c] = 4
    for b in barriers:
        out[b] = [2]*w
    return out

